
function calculate4Pillars(lowerText, lang = 'vi') {
  const bocucKeywords = ['rule of thirds', 'golden ratio', 'fibonacci', 'leading lines', 'frame in frame', 'symmetry', 'low angle', 'high angle', 'depth of field', 'anamorphic', 'scale contrast', 'rhythm'];
  const bocucScore = Math.min(100, Math.max(30, bocucKeywords.filter(k => lowerText.includes(k)).length * 20 + 20));
  const anhsangKeywords = ['chiaroscuro', 'rembrandt', 'volumetric', 'rim light', 'negative space', 'breathing room', 'anti-horror-vacui', 'motivated light', 'key light', 'golden hour'];
  const anhsangScore = Math.min(100, Math.max(30, anhsangKeywords.filter(k => lowerText.includes(k)).length * 22 + 15));
  const mausacKeywords = ['color harmony', 'dominant color', 'dominant palette', '80% dominant', 'monochromatic', 'tonal contrast', 'warm-cool', 'teal and orange', 'kodak', 'portra', 'cinestill'];
  const mausacScore = Math.min(100, Math.max(30, mausacKeywords.filter(k => lowerText.includes(k)).length * 22 + 15));
  const chatlieuKeywords = ['texture', 'raking light', 'somatosensory', 'micro-relief', 'tactile', 'volumetric haze', 'atmosphere', 'visual hierarchy', 'anchor point', 'unity', 'gestalt'];
  const chatlieuScore = Math.min(100, Math.max(30, chatlieuKeywords.filter(k => lowerText.includes(k)).length * 22 + 15));
  return {
    bocuc: { score: bocucScore, label: 'Bố Cục', color: '#7c8aff' },
    anhsang: { score: anhsangScore, label: 'Ánh Sáng', color: '#ffcb6b' },
    mausac: { score: mausacScore, label: 'Màu Sắc', color: '#f07178' },
    chatlieu: { score: chatlieuScore, label: 'Chất Liệu', color: '#c3e88d' },
    averageScore: Math.round((bocucScore + anhsangScore + mausacScore + chatlieuScore) / 4)
  };
}


